// n8n fires this workflow whenever a job that names it as its "Error
// Workflow" fails. Payload shape: { execution: { id, url, error,
// lastNodeExecuted, mode }, workflow: { id, name } }. Build a readable
// email from it. NOTE: n8n only triggers on a REAL failure -- not on
// normal no-ops (a job that finds nothing new, or skips an already-sent
// item), so those never page anyone.
const t = $json || {};
const e = t.execution || {};
const wf = t.workflow || {};
const errMsg = (e.error && (e.error.message || e.error.description)) || 'Unknown error';
const node = e.lastNodeExecuted || 'unknown step';
const when = new Date().toISOString();
const mode = e.mode || 'unknown';

const subject = `SCL job failed: ${wf.name || 'unknown workflow'}`;
const body = [
  `A scheduled/triggered n8n job failed.`,
  ``,
  `Workflow:   ${wf.name || wf.id || 'unknown'}`,
  `Failed at:  ${node}`,
  `Error:      ${errMsg}`,
  `Run mode:   ${mode}`,
  `Time (UTC): ${when}`,
  e.url ? `Execution:  ${e.url}` : '',
  ``,
  `-- Automated alert from the SCL n8n error handler.`,
].filter((l) => l !== undefined && l !== null).join('\n');

return [{ json: { subject, body } }];
